{"command":"@'
$lines = Get-Content -LiteralPath 'src/main/resources/spec/[RS]+OM_GSE+integration+with+local+CBR.doc'
$capturing = $false
$ready = $false
$sb = New-Object System.Text.StringBuilder
foreach ($line in $lines) {
    if ($capturing) {
        if ($line -like "------=*") { break }
        $null = $sb.Append($line)
        continue
    }
    if ($ready) {
        if ($line -eq "") { $capturing = $true }
        continue
    }
    if ($line -like "Content-Type: text/html*") { $ready = $true }
}
$base64 = $sb.ToString()
$htmlBytes = [Convert]::FromBase64String($base64)
$html = [Text.Encoding]::Unicode.GetString($htmlBytes)
[IO.File]::WriteAllText('src/main/resources/spec/RS_OM_GSE_integration_with_local_CBR.html', $html, [Text.Encoding]::UTF8)
Write-Host "Extracted $($html.Length) chars"
'@ | powershell -NoLogo -NoProfile -Command -"}

