-- - Address country/text izbaceni; dodate postal address kolone.
-- - Dodati DR/CR statistical code u glavnu tabelu.
-- - EVENT_DATE/COUNTRY iz child tabele obrisani.
-- - Request tabela sadrzi samo sirovi XML + status/izvor.

CREATE SEQUENCE TBL_CBR_TRANSACTION_REQUEST_SEQ START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
